import Redis from 'ioredis';
const redis = new Redis();

// Script: get a value and multiply it
const script = `
  local val = redis.call('GET', KEYS[1])
  if not val then return 0 end
  return tonumber(val) * tonumber(ARGV[1])
`;

// EVAL: numkeys=1, key='counter:hits', argv='10'
const result = await redis.eval(script, 1, 'counter:hits', '10');
console.log(result);  // current value * 10

// Cache script by SHA for efficiency
const sha = await redis.script('LOAD', script);
// Use EVALSHA on subsequent calls (no retransmit of script text)
const result2 = await redis.evalsha(sha, 1, 'counter:hits', '10');

// Atomic rate limiter: increment counter, set expiry if first request
const rateLimitScript = `
  local current = redis.call('INCR', KEYS[1])
  if current == 1 then
    redis.call('EXPIRE', KEYS[1], tonumber(ARGV[1]))
  end
  return current
`;

async function checkRateLimit(userId, limit = 100, windowSecs = 60) {
  const key = `rate:${userId}:${Math.floor(Date.now() / (windowSecs * 1000))}`;
  const count = await redis.eval(rateLimitScript, 1, key, windowSecs);
  return count > limit;  // true = rate limited
}

// Acquire lock: SET NX EX (native command, no Lua needed for acquire)
async function acquireLock(resource, ttlSecs = 30) {
  const token = crypto.randomUUID();
  const acquired = await redis.set(
    `lock:${resource}`, token,
    'NX', 'EX', ttlSecs
  );
  return acquired ? token : null;
}

// Release lock: MUST check token matches before deleting (Lua!)
const releaseLockScript = `
  if redis.call('GET', KEYS[1]) == ARGV[1] then
    return redis.call('DEL', KEYS[1])
  else
    return 0
  end
`;

async function releaseLock(resource, token) {
  // Atomic check-and-delete: only delete if token matches
  // Without Lua, another process could acquire the lock between our GET and DEL
  return redis.eval(releaseLockScript, 1, `lock:${resource}`, token);
}
